// Get tasks from Kanboard response
const response = $input.first().json;
const tasks = response.result || [];

console.log(`Total tasks found: ${tasks.length}`);

// Filter tasks that need AI enhancement (empty or short descriptions)
const tasksNeedingAI = tasks.filter(task => {
  const description = task.description || '';
  const title = task.title || '';
  const needsEnhancement = description.trim().length < 20 && title.trim().length > 0;

  if (needsEnhancement) {
    console.log(`Task "${title}" (ID: ${task.id}) needs AI enhancement`);
  }

  return needsEnhancement;
});

console.log(`Tasks needing AI enhancement: ${tasksNeedingAI.length}`);

// Always return at least one item to continue execution
if (tasksNeedingAI.length === 0) {
  console.log('No tasks need enhancement - returning empty execution signal');
  return [{ json: { skip: true, message: 'No tasks need enhancement' } }];
}

// Return ONLY the first task to avoid overwhelming the AI
const firstTask = tasksNeedingAI[0];
console.log(`Processing first task: "${firstTask.title}" (ID: ${firstTask.id})`);

return [{ 
  json: {
    id: firstTask.id,
    title: firstTask.title,
    description: firstTask.description || '',
    project_id: firstTask.project_id || 1
  }
}];

