  "complexity": 3,
  "tags": ["tag1", "tag2", "tag3"]
}

No other text, just the JSON:",
  "stream": false
}

parameters.functionCode:
// Get task data from the filter node
const allFilteredData = $('Filter Tasks Needing AI').all();
const currentTaskData = allFilteredData[0].json; // Get the first (current) task

// Get AI response
const aiResponse = $input.first().json.response;

console.log(`Processing task: ${currentTaskData.title}`);
console.log(`AI response received: ${aiResponse.substring(0, 100)}...`);

// Parse AI response to extract JSON
let enhancedData = null;
try {
  // Look for JSON block in the response
  const jsonMatch = aiResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    enhancedData = JSON.parse(jsonMatch[0]);
    console.log('Successfully parsed AI JSON');
  } else {
    throw new Error('No JSON found in AI response');
  }
} catch (error) {
  console.log(`JSON parsing failed: ${error.message}`);
  // Create fallback enhancement
  enhancedData = {
    description: `AI Enhanced: ${currentTaskData.title}. This task requires careful analysis and implementation to achieve the desired outcome effectively.`,
    complexity: 3,
    tags: ["ai-enhanced", "auto-generated", "needs-review"]
  };
}

// Prepare final data for Kanboard update
const result = {
  task_id: parseInt(currentTaskData.id),
  title: currentTaskData.title,
  enhanced_description: enhancedData.description,
  complexity: enhancedData.complexity || 3,
  tags_string: Array.isArray(enhancedData.tags) ? enhancedData.tags.join(', ') : 'ai-enhanced'
};

console.log(`Prepared update for task ${result.task_id}: ${result.title}`);

return { json: result };

